[{"category":"section","location":"#CompactBasisFunctions","page":"Home","text":"","title":"CompactBasisFunctions"},{"category":"type","location":"#CompactBasisFunctions.Bernstein","page":"Home","text":"Bernstein basis on the interval [0..1].\n\n\n\n\n\n","title":"CompactBasisFunctions.Bernstein"},{"category":"type","location":"#CompactBasisFunctions.Chebyshev","page":"Home","text":"Chebyshev basis of the first (kind = 1) or second (kind = 2) kind on the interval [0..1].\n\nThe basis functions are the Chebyshev polynomials evaluated at 2x-1, and the nodes are the Chebyshev points shifted onto [0..1] and returned in ascending order.\n\nT is the element type of the nodes, and must be able to represent them. This means a floating-point type in general; an integer-like T only works in the special cases where the nodes are exactly representable, such as ChebyshevU(Integer, 2), whose nodes are 0 and 1. Otherwise the constructor throws an InexactError.\n\n\n\n\n\n","title":"CompactBasisFunctions.Chebyshev"},{"category":"type","location":"#CompactBasisFunctions.Lagrange","page":"Home","text":"Lagrange basis on the interval [0..1].\n\n\n\n\n\n","title":"CompactBasisFunctions.Lagrange"},{"category":"type","location":"#CompactBasisFunctions.Legendre","page":"Home","text":"Legendre basis on the interval [0..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions.Legendre"},{"category":"method","location":"#CompactBasisFunctions._chebyshev-Union{Tuple{T}, Tuple{Val{1}, Int64, T}} where T","page":"Home","text":"Chebyshev polynomial of the first kind on the interval [-1..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions._chebyshev"},{"category":"method","location":"#CompactBasisFunctions._chebyshev-Union{Tuple{T}, Tuple{Val{2}, Int64, T}} where T","page":"Home","text":"Chebyshev polynomial of the second kind on the interval [-1..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions._chebyshev"},{"category":"method","location":"#CompactBasisFunctions._eval-Union{Tuple{DT}, Tuple{ArrayLayouts.Mul{<:Any, <:Any, <:Derivative, <:ChebyshevT{T} where T}, DT, Int64}} where DT","page":"Home","text":"Evaluate derivative of Chebyshev polynomial of the first kind on the interval [0..1].\n\n\n\n\n\n","title":"CompactBasisFunctions._eval"},{"category":"method","location":"#CompactBasisFunctions._eval-Union{Tuple{DT}, Tuple{ArrayLayouts.Mul{<:Any, <:Any, <:Derivative, <:ChebyshevU{T} where T}, DT, Int64}} where DT","page":"Home","text":"Evaluate derivative of Chebyshev polynomial of the second kind on the interval [0..1].\n\n\n\n\n\n","title":"CompactBasisFunctions._eval"},{"category":"method","location":"#CompactBasisFunctions._eval-Union{Tuple{DT}, Tuple{ArrayLayouts.Mul{<:Any, <:Any, <:Derivative, <:Legendre}, DT, Int64}} where DT","page":"Home","text":"Evaluate derivative of Legendre polynomial on the interval [0..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions._eval"},{"category":"method","location":"#CompactBasisFunctions._legendre-Union{Tuple{T}, Tuple{Int64, T}} where T","page":"Home","text":"Legendre polynomial on the interval [-1..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions._legendre"},{"category":"method","location":"#CompactBasisFunctions._legendre_derivative-Union{Tuple{T}, Tuple{Int64, T}} where T","page":"Home","text":"Derivative of Legendre polynomial on the interval [-1..+1].\n\n\n\n\n\n","title":"CompactBasisFunctions._legendre_derivative"}]
